def build(repo_root: Path = Path(__file__).resolve().parent.parent):
    for rel_path, payload in PACKAGES.items():
        target = repo_root / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        with open(target, "w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2, ensure_ascii=False)
        print(f"Wrote {rel_path} (baseline={payload.get('baseline_version')}, ops={len(payload['body']['operations'])})")


if __name__ == "__main__":
    build()
